/**
 * Tailwind v4 theme fragment. Each colour maps to a CSS variable so one class works in both themes.
 * Consumed by apps/admin/src/app/globals.css via `@theme` (generated by scripts/gen-tailwind-theme.ts)
 * and exported here for tooling.
 */
import { palette } from './colors';
import { fontSizes, letterSpacing } from './typography';
import { radii, space } from './layout';

const kebab = (s: string) => s.replace(/([a-z0-9])([A-Z])/g, '$1-$2').toLowerCase();

export function tailwindThemeBlock(): string {
  const lines: string[] = ['@theme inline {'];
  for (const k of Object.keys(palette)) lines.push(`  --color-${kebab(k)}: var(--sw-${kebab(k)});`);
  lines.push(`  --font-display: var(--sw-font-display);`);
  lines.push(`  --font-sans: var(--sw-font-sans);`);
  lines.push(`  --font-mono: var(--sw-font-mono);`);
  for (const [k, v] of Object.entries(fontSizes)) lines.push(`  --text-${k}: ${v}px;`);
  for (const [k, v] of Object.entries(letterSpacing)) lines.push(`  --tracking-${k}: ${v}em;`);
  for (const [k, v] of Object.entries(radii)) lines.push(`  --radius-${k}: ${v}px;`);
  for (const [k, v] of Object.entries(space)) lines.push(`  --spacing-${String(k).replace('.', '_')}: ${v}px;`);
  lines.push(`  --shadow-floating: var(--sw-shadow-floating);`);
  lines.push(`  --shadow-sheet: var(--sw-shadow-sheet);`);
  lines.push(`  --shadow-sticky: var(--sw-shadow-sticky);`);
  lines.push(`  --ease-atelier: var(--sw-ease-atelier);`);
  lines.push('}');
  return lines.join('\n');
}
